mapper.select:

where r.del_flag = '0'

	AND r.role_name like concat(concat('%',#{roleName}),'%')


	AND r.status = #{status}


	AND r.role_key like concat(concat('%',#{roleKey}),'%')


	AND r.data_scope = #{dataScope}


    and r.create_time >= to_date(#{beginTime},'yyyy-MM-dd HH24:mi:ss')


    and r.create_time <= to_date(#{endTime},'yyyy-MM-dd HH24:mi:ss')


${params.dataScope}
order by r.role_sort asc

mapper.update:
update sys_role
role_name = #{roleName}, role_key = #{roleKey}, role_sort = #{roleSort}, data_scope = #{dataScope}, menu_check_strictly = #{menuCheckStrictly}, dept_check_strictly = #{deptCheckStrictly}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate
where role_id = #{roleId}
